def main():
    import sys
    import heapq

    def read_ints():
        return map(int, sys.stdin.readline().split())

    n, r, avg = read_ints()
    total_required = n * avg
    current_total = 0
    max_heap = []

    for _ in range(n):
        a_i, b_i = read_ints()
        current_total += a_i
        if a_i < r:
            heapq.heappush(max_heap, (-b_i, a_i))

    if current_total >= total_required:
        print(0)
        return

    needed_increase = total_required - current_total
    essays_needed = 0

    while max_heap and needed_increase > 0:
        b_i, a_i = heapq.heappop(max_heap)
        b_i = -b_i
        max_possible_increase = min(r - a_i, needed_increase)
        essays_needed += max_possible_increase * b_i
        needed_increase -= max_possible_increase

    if needed_increase == 0:
        print(essays_needed)
    else:
        print(-1)

if __name__ == "__main__":

